<?php declare(strict_types=1);$base=config('app.base_path');$trash=!empty($trash);?><div class="page-header"><div><h1><?= $trash?'Deleted Tour Packages':'Tour Packages' ?></h1><p>Build bookable itineraries from reusable Manipur destinations.</p></div><div class="page-actions"><?php if($trash):?><a class="btn btn-secondary" href="<?= $base ?>/tourism/packages">Active Packages</a><?php else:?><a class="btn btn-secondary" href="<?= $base ?>/tourism/packages?view=trash">Trash</a><a class="btn btn-primary" href="<?= $base ?>/tourism/packages/create">Add Package</a><?php endif;?></div></div><div class="card table-responsive"><table class="table"><thead><tr><th>Package</th><th>Provider</th><th>Duration</th><th>Price</th><th>Destinations</th><th>Status</th><th>Actions</th></tr></thead><tbody><?php if(empty($packages)):?><tr><td colspan="7"><div class="empty-state">No tour packages found.</div></td></tr><?php else:foreach($packages as $p):?><tr><td><strong><?= htmlspecialchars($p['title'],ENT_QUOTES,'UTF-8')?></strong></td><td><?= htmlspecialchars((string)($p['provider_name']??'Independent'),ENT_QUOTES,'UTF-8')?></td><td><?= (int)$p['duration_days']?>D / <?= (int)$p['duration_nights']?>N</td><td>₹<?= number_format((float)($p['discount_price']??$p['base_price']),2)?> <small>/ <?= $p['pricing_type']==='PER_GROUP'?'group':'person'?></small></td><td><?= (int)$p['destination_count']?></td><td><?= htmlspecialchars($p['status'],ENT_QUOTES,'UTF-8')?></td><td><?php if($trash):?><form method="post" action="<?= $base ?>/tourism/packages/<?= (int)$p['id']?>/restore"><button class="btn btn-secondary">Restore</button></form><?php else:?><a class="link-button" href="<?= $base ?>/tourism/packages/<?= (int)$p['id']?>">View</a> <a class="link-button" href="<?= $base ?>/tourism/packages/<?= (int)$p['id']?>/edit">Edit</a><?php endif;?></td></tr><?php endforeach;endif;?></tbody></table></div>